    /// Fast string selection based on current language (supports common UI glossary for all 37 languages,
    /// falling back to Russian for `Ru` and English for others).
    #[inline]
    pub fn tr<'a>(self, ru: &'a str, en: &'a str) -> &'a str {
        match self {
            AppLanguage::Ru => ru,
            AppLanguage::En => en,
            other => translate_common_phrase(other, ru).unwrap_or(en),
        }
    }

