#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_asian_translations_dont_fallback_to_english() {
        assert_eq!(AppLanguage::Ja.tr("Инструмент:", "Tool:"), "ツール:");
        assert_eq!(AppLanguage::ZhCn.tr("Инструмент:", "Tool:"), "工具:");
        assert_eq!(AppLanguage::Ko.tr("Инструмент:", "Tool:"), "도구:");

        assert_eq!(
            AppLanguage::Ja.tr("⊞ Выровнять окна", "⊞ Equal Views"),
            "⊞ ウィンドウ均等化"
        );
        assert_eq!(
            AppLanguage::ZhCn.tr("⊞ Выровнять окна", "⊞ Equal Views"),
            "⊞ 均分视图"
        );
        assert_eq!(
            AppLanguage::Ko.tr("⊞ Выровнять окна", "⊞ Equal Views"),
            "⊞ 창 크기 균등화"
        );

        assert_eq!(
            AppLanguage::Ja.tr("Карта раскроя", "Cutting Layout"),
            "木取り図"
        );
        assert_eq!(
            AppLanguage::ZhCn.tr("Карта раскроя", "Cutting Layout"),
            "排料裁切图"
        );
        assert_eq!(
            AppLanguage::Ko.tr("Карта раскроя", "Cutting Layout"),
            "재단 배치도"
        );

        assert_eq!(
            AppLanguage::Ja.tr("Ширина реза фрезы/пилы:", "Saw kerf width:"),
            "ノコ刃の切削幅:"
        );
    }

    #[test]
    fn test_adapt_shortcuts_logic() {
        let orig = "Save (Ctrl+S) and Copy (Ctrl+C), Shift/Ctrl + click";
        if is_macos_platform() {
            let adapted = adapt_shortcuts(orig);
            assert_eq!(adapted, "Save (Cmd+S) and Copy (Cmd+C), Shift/Cmd + click");
        } else {
            let adapted = adapt_shortcuts(orig);
            assert_eq!(adapted, orig);
        }
    }
}
